  - name: "Keine Transaktionskosten"
    condition: "true"
    expression: "0.0"
custody:
  periods:
    - validFrom: "1900-01-01"
      status: VERIFIED
      source: "https://www.migrosbank.ch/dam/downloads/de/broschuere/preis-broschuere"
      note: "The pension custody account holds only Migros Bank pension funds and has never been charged a custody fee."
      currency: CHF
      valuation: NONE
      billingMonths: 3
      collection: START
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      amount: \'0\'
', NULL);
  # Schweizer Börse ab CHF 100\'000 (offizieller Zuschlag + Ausführungsgebühr)
  - name: "Börsenplatz Schweiz ab CHF 100\'000"
    condition: \'tradeValue >= 100000 && mic == "XSWX"\'
    expression: "40.0 + tradeValue * 0.00035"

  # Schweizer Börse unter CHF 100\'000 (Pauschale + Ausführungsgebühr Börse ~0.015%)
  - name: "Börsenplatz Schweiz"
    condition: \'mic == "XSWX"\'
    expression: "40.0 + tradeValue * 0.00015"

  # Ausland ab CHF 100\'000 (offizieller Zuschlag + Ausführungsgebühr)
  - name: "Börsenplatz Ausland ab CHF 100\'000"
    condition: "tradeValue >= 100000"
    expression: "40.0 + tradeValue * 0.0012"

  # Standard-Pauschale (inkl. geschätzte Ausführungsgebühr Ausland ~0.015%)
  - name: "Standard E-Banking Pauschale"
    condition: "true"
    expression: "40.0 + tradeValue * 0.00015"
custody:
  periods:
    - validFrom: "1900-01-01"
      status: ASSUMED
      source: "https://www.migrosbank.ch/dam/downloads/de/broschuere/preis-broschuere"
      note: "Approximation: the June 2026 tariff applied to the whole history. 0.230, 0.210 or 0.190 percent a year below CHF 750,000, below CHF 1.5 million or above, the reached tier on the whole volume; calculated monthly on the month-end value, billed quarterly; CHF 50 annual minimum per account as 12.50 per quarter; plus VAT at today\'s rate. Migros Bank funds (half rate) are charged at the normal rate, and the annual billing of earlier brochures is not modelled."
      currency: CHF
      valuation: MONTHLY
      observationDay: 0
      billingMonths: 3
      collection: END
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      closingPolicy: ACCRUED
      amount: \'assetValue * IF(accountValue < 750000, 0.0023, IF(accountValue < 1500000, 0.0021, 0.0019))\'
      minimum: 12.5
      vatRate: 0.081

fx:
  amountCurrency: CHF
  periods:
    - validFrom: "1900-01-01"
      status: ASSUMED
      source: "https://www.migrosbank.ch/de/privatpersonen/konten-karten/noten-devisenkurse.html"
      note: "The price list charges foreign-currency settlements at the current exchange rate without a separate fee; the margin is in the rate. About 1.5% up to CHF 50,000 and about 1% up to CHF 250,000, estimated 2026-09 from the non-binding rate table and a secondary source, for all currencies and conversion kinds and the whole history. Above CHF 250,000 the 1% band is assumed to continue."
      rules:
        - name: Up to CHF 50,000
          condition: "tierAmount <= 50000"
          expression: "1.5"
        - name: Up to CHF 250,000
          condition: "tierAmount <= 250000"
          expression: "1.0"
        - name: Above CHF 250,000 (assumed continuation of the band below)
          condition: "true"
          expression: "1.0"
', NULL);
# PostFinance E-Trading Gebührenmodell (kalibriert)
# Stand: 1. Januar 2026
# ============================================================================
# Kalibrierung:
#   - Basierend auf 749 verglichenen Transaktionen (2006–2023).
#   - Transaktionen mit Depotgebühren-Gutschrift (Anfang Jahr/Quartal)
#     sowie 2024/2025-Daten wurden bei der Kalibrierung ausgeschlossen.
#   - SIX-Gebühren enthalten neben der Courtage auch Börsengebühren
#     (Umsatzabgabe, SIX Trading Fee etc.).
#   - Bei Obligationen können Stückzinsen den Abrechnungsbetrag über die
#     nächste Tarifstufe heben – dies ist modellbedingt nicht abbildbar.
# ============================================================================

rules:

  # ==========================================================================
  # FONDS
  # ==========================================================================
  - name: "Fonds Zeichnung (Subscription)"
    condition: \'instrument == "MUTUAL_FUND" && tradeDirection == 0\'
    expression: "MAX(20.0, MIN(1000.0, tradeValue * 0.01))"

  - name: "Fonds Rücknahme (Redemption)"
    condition: \'instrument == "MUTUAL_FUND" && tradeDirection == 1\'
    expression: "0.0"

  # ==========================================================================
  # SPARPLÄNE
  # ==========================================================================
  - name: "Sparplan Ausführung"
    condition: \'instrument == "PENSION_FUNDS"\'
    expression: "MAX(1.0, tradeValue * 0.01)"

  # ==========================================================================
  # OBLIGATIONEN OTC
  # ==========================================================================
  - name: "Obligationen OTC"
    condition: \'assetclass == "FIXED_INCOME" && mic == "OTCB"\'
    expression: "MAX(50.0, tradeValue * 0.0025)"

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 1: SIX Swiss Exchange, BX Swiss (CHF)
  # MICs: XSWX, XBRN
  # --------------------------------------------------------------------------
  # Kalibriert auf Basis von ~500 Transaktionen. Enthält Courtage plus
  # Börsengebühren. Typische Ist-Werte pro Stufe:
  #   ≤ 5\'000:   ~27–29      ≤ 20\'000:  ~72–73
  #   ≤ 10\'000:  ~37–38.50   ≤ 30\'000:  ~97–101
  #   ≤ 15\'000:  ~52–53.50   ≤ 50\'000:  ~132–135
  # ==========================================================================
  - name: "SIX Swiss Exchange / BX Swiss"
    condition: \'mic == "XSWX" || mic == "XBRN"\'
    expression: >-
      IF(tradeValue <= 500, 8.0,
      IF(tradeValue <= 1000, 15.0,
      IF(tradeValue <= 5000, 28.0,
      IF(tradeValue <= 10000, 38.0,
      IF(tradeValue <= 15000, 53.0,
      IF(tradeValue <= 20000, 73.0,
      IF(tradeValue <= 30000, 100.0,
      IF(tradeValue <= 50000, 135.0,
      IF(tradeValue <= 100000, 185.0,
      IF(tradeValue <= 150000, 265.0,
      330.0))))))))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 2: SIX Structured Products, Off-exchange Switzerland
  # MICs: XSTX, OFCH
  # ==========================================================================
  - name: "SIX Structured Products / Off-exchange CH"
    condition: \'mic == "XSTX" || mic == "OFCH"\'
    expression: >-
      IF(tradeValue <= 1000, 15.0,
      IF(tradeValue <= 5000, 25.0,
      IF(tradeValue <= 10000, 38.0,
      IF(tradeValue <= 15000, 50.0,
      IF(tradeValue <= 20000, 70.0,
      IF(tradeValue <= 30000, 95.0,
      95.0))))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 3: Swiss DOTS (CHF)
  # MIC: SDOT
  # ==========================================================================
  - name: "Swiss DOTS"
    condition: \'mic == "SDOT"\'
    expression: >-
      IF(tradeValue <= 1000, 9.0,
      IF(tradeValue <= 5000, 12.0,
      IF(tradeValue <= 10000, 20.0,
      IF(tradeValue <= 50000, 28.0,
      36.0))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 4: Europäische Börsen (EUR)
  # MICs: XFRA, XETR, XPAR, XAMS, XBRU, XCSE, XSTO, XHEL, XMIL, XMAD, XWBO
  # --------------------------------------------------------------------------
  # Kalibriert: Mindestgebühr 35 CHF, konsistent über alle Transaktionen.
  #   ≤ 5\'000:  immer 35    ≤ 10\'000: 40    ≤ 15\'000: 50
  # ==========================================================================
  - name: "Europäische Börsen (EUR)"
    condition: >-
      mic == "XFRA" || mic == "XETR" || mic == "XPAR" ||
      mic == "XAMS" || mic == "XBRU" || mic == "XCSE" ||
      mic == "XSTO" || mic == "XHEL" || mic == "XMIL" ||
      mic == "XMAD" || mic == "XWBO"
    expression: >-
      IF(tradeValue <= 5000, 35.0,
      IF(tradeValue <= 10000, 40.0,
      IF(tradeValue <= 15000, 50.0,
      IF(tradeValue <= 20000, 65.0,
      IF(tradeValue <= 30000, 90.0,
      IF(tradeValue <= 50000, 120.0,
      IF(tradeValue <= 100000, 180.0,
      IF(tradeValue <= 150000, 260.0,
      320.0))))))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 5: EUWAX, Off-exchange Germany (EUR)
  # MICs: XSTU, OFDE
  # ==========================================================================
  - name: "EUWAX / Off-exchange DE"
    condition: \'mic == "XSTU" || mic == "OFDE"\'
    expression: >-
      IF(tradeValue <= 1000, 15.0,
      IF(tradeValue <= 5000, 25.0,
      IF(tradeValue <= 10000, 35.0,
      IF(tradeValue <= 15000, 45.0,
      IF(tradeValue <= 20000, 65.0,
      IF(tradeValue <= 30000, 90.0,
      90.0))))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 6: London Stock Exchange (GBP)
  # MIC: XLON
  # ==========================================================================
  - name: "London Stock Exchange (GBP)"
    condition: \'mic == "XLON"\'
    expression: >-
      IF(tradeValue <= 5000, 35.0,
      IF(tradeValue <= 10000, 40.0,
      IF(tradeValue <= 15000, 50.0,
      IF(tradeValue <= 20000, 65.0,
      IF(tradeValue <= 30000, 90.0,
      IF(tradeValue <= 50000, 120.0,
      IF(tradeValue <= 100000, 180.0,
      IF(tradeValue <= 150000, 260.0,
      320.0))))))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 7: NYSE, NASDAQ, NYSE American (USD)
  # MICs: XNYS, XNAS, XASE
  # --------------------------------------------------------------------------
  # Kalibriert: ≤ 5\'000 → 35 (beobachtet bei TV 3\'000–3\'600)
  # ==========================================================================
  - name: "US-Börsen (USD)"
    condition: \'mic == "XNYS" || mic == "XNAS" || mic == "XASE"\'
    expression: >-
      IF(tradeValue <= 5000, 35.0,
      IF(tradeValue <= 10000, 40.0,
      IF(tradeValue <= 15000, 50.0,
      IF(tradeValue <= 20000, 65.0,
      IF(tradeValue <= 30000, 90.0,
      IF(tradeValue <= 50000, 120.0,
      IF(tradeValue <= 100000, 180.0,
      IF(tradeValue <= 150000, 260.0,
      320.0))))))))

  # ==========================================================================
  # BÖRSENPLATZ-GRUPPE 8: Toronto TSX, TSX Venture (CAD)
  # MICs: XTSE, XTSX
  # ==========================================================================
  - name: "Kanadische Börsen (CAD)"
    condition: \'mic == "XTSE" || mic == "XTSX"\'
    expression: >-
      IF(tradeValue <= 5000, 35.0,
      IF(tradeValue <= 10000, 40.0,
      IF(tradeValue <= 15000, 50.0,
      IF(tradeValue <= 20000, 65.0,
      IF(tradeValue <= 30000, 90.0,
      IF(tradeValue <= 50000, 120.0,
      IF(tradeValue <= 100000, 180.0,
      IF(tradeValue <= 150000, 260.0,
      320.0))))))))

  # ==========================================================================
  # AUFFANGREGEL (Fallback)
  # ==========================================================================
  - name: "Standard (unbekannter Börsenplatz)"
    condition: "true"
    expression: >-
      IF(tradeValue <= 5000, 35.0,
      IF(tradeValue <= 10000, 40.0,
      IF(tradeValue <= 15000, 50.0,
      IF(tradeValue <= 20000, 65.0,
      IF(tradeValue <= 30000, 90.0,
      IF(tradeValue <= 50000, 120.0,
      IF(tradeValue <= 100000, 180.0,
      IF(tradeValue <= 150000, 260.0,
      320.0))))))))
custody:
  periods:
    - validFrom: "1900-01-01"
      validTo: "2023-12-31"
      status: ASSUMED
      source: "https://forum.mustachianpost.com/t/postfinance-e-trading-new-fee-structure-2024/11293"
      note: "Approximation: the fee valid until December 2023 applied to the whole earlier history. CHF 90 a year including VAT, billed in advance on 1 January and credited against the online trading commissions of the same year; unused credit expires at year end."
      currency: CHF
      valuation: NONE
      billingMonths: 12
      collection: START
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      amount: \'90\'
      creditAmount: 90
      creditEligibility: \'instrument != "FOREX" && instrument != "CFD"\'
    - validFrom: "2024-01-01"
      status: VERIFIED
      source: "https://www.postfinance.ch/content/dam/pfch/doc/480_499/482_22_en.pdf"
      note: "CHF 72 a year including VAT since January 2024, billed as CHF 18 at the start of each quarter. Credits expire each quarter; eligible online trades only, never corporate actions or taxes. Offline-only instruments require an account eligibility override."
      currency: CHF
      valuation: NONE
      billingMonths: 3
      collection: START
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      amount: \'18\'
      creditAmount: 18
      creditEligibility: \'instrument != "FOREX" && instrument != "CFD"\'

