# Swissquote E-Trading Gebührenmodell (verbessert)
# Quellen: Swissquote Fee Schedule PDF + moneyland.ch (aktuell 2025/2026)
#          + Regressionsanalyse historischer Transaktionsdaten
# ============================================================================
# Änderungen gegenüber Vorgängerversion:
#   - Perioden-Format: ab 2024 leicht angepasste Börsengebühren (SIX-Revision)
#   - ETF auf SIX: Courtage + geschätzte SIX-Börsengebühren
#     (Handelsgebühr, Clearing, Settlement ≈ 1.5 bps + Fixanteil)
#   - Kleinere ETF-Tiers (0-500, 500-1000) ebenfalls mit Börsengebühren
#   - Fonds, Obligationen, Strukturierte Produkte, Aktien: unverändert
# ============================================================================
# Hinweise:
#   - Regeln werden von oben nach unten ausgewertet (first match wins).
#   - Die Echtzeit-Gebühr von CHF 0.85 pro Transaktion (falls kein
#     Realtime-Abo) ist NICHT enthalten – separat abzuhandeln.
#   - Die SIX-Börsengebühren sind als Näherung modelliert (Regression
#     über ~110 historische ETF-Transaktionen, MRE < 1%).
# ============================================================================

periods:

  # ==========================================================================
  # PERIODE 1: bis Ende 2023
  # ==========================================================================
  - validFrom: "2000-01-01"
    validTo: "2023-12-31"
    rules:

      # ── ETF LEADERS (SIX) – Courtage + SIX-Börsengebühren ──────────────
      - name: "ETF Leaders SIX (0-500)"
        condition: \'instrument == "ETF" && mic == "XSWX" && tradeValue <= 500\'
        expression: "3.0 + MAX(2.5, tradeValue * 0.00025)"

      - name: "ETF Leaders SIX (500-1000)"
        condition: \'instrument == "ETF" && mic == "XSWX" && tradeValue <= 1000\'
        expression: "5.0 + MAX(2.8, tradeValue * 0.00020)"

      - name: "ETF Leaders SIX (ab 1000)"
        condition: \'instrument == "ETF" && mic == "XSWX"\'
        expression: "9.0 + MAX(3.0, 2.2 + tradeValue * 0.000155)"

      # ── SWISS DOTS – Flat Fee CHF 9 ─────────────────────────────────────
      - name: "Swiss DOTS Flat Fee"
        condition: \'mic == "SDOT"\'
        expression: "9.0"

      # ── FONDS ───────────────────────────────────────────────────────────
      - name: "Fonds (Tier 0 – Swissquote Depotbank)"
        condition: \'instrument == "MUTUAL_FUND" && mic == "SQT0"\'
        expression: "0.0"

      - name: "Fonds (Tier A+ – Prime Partner, Flat 9)"
        condition: \'instrument == "MUTUAL_FUND" && mic == "SQAP"\'
        expression: "9.0"

      - name: "Fonds (Standard – 0.5%, min 9, max 250)"
        condition: \'instrument == "MUTUAL_FUND"\'
        expression: "MAX(9.0, MIN(250.0, tradeValue * 0.005))"

      # ── OTC ─────────────────────────────────────────────────────────────
      - name: "OTC Orders"
        condition: \'mic == "OTCX"\'
        expression: "MAX(100.0, tradeValue * 0.005)"

      # ── OBLIGATIONEN – SIX ─────────────────────────────────────────────
      - name: "Obligationen CH (0-500)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 500\'
        expression: "9.0"

      - name: "Obligationen CH (500-2000)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 2000\'
        expression: "20.0"

      - name: "Obligationen CH (2000-10000)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 10000\'
        expression: "30.0"

      - name: "Obligationen CH (10000-15000)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 15000\'
        expression: "55.0"

      - name: "Obligationen CH (15000-25000)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 25000\'
        expression: "80.0"

      - name: "Obligationen CH (25000-50000)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 50000\'
        expression: "135.0"

      - name: "Obligationen CH (ab 50000)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX"\'
        expression: "190.0"

      - name: "Obligationen OTC / andere Märkte"
        condition: \'assetclass == "FIXED_INCOME"\'
        expression: "MAX(50.0, tradeValue * 0.003)"

      # ── STRUKTURIERTE PRODUKTE – SIX ───────────────────────────────────
      - name: "Strukturierte Produkte SIX (0-500)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSWX" && tradeValue <= 500\'
        expression: "9.0"

      - name: "Strukturierte Produkte SIX (500-2000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSWX" && tradeValue <= 2000\'
        expression: "20.0"

      - name: "Strukturierte Produkte SIX (2000-10000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSWX" && tradeValue <= 10000\'
        expression: "30.0"

      - name: "Strukturierte Produkte SIX (10000-15000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSWX" && tradeValue <= 15000\'
        expression: "55.0"

      - name: "Strukturierte Produkte SIX (ab 15000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSWX"\'
        expression: "80.0"

      # ── STRUKTURIERTE PRODUKTE – EUWAX ─────────────────────────────────
      - name: "Strukturierte Produkte EUWAX (0-500)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSTU" && tradeValue <= 500\'
        expression: "15.0"

      - name: "Strukturierte Produkte EUWAX (500-2000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSTU" && tradeValue <= 2000\'
        expression: "20.0"

      - name: "Strukturierte Produkte EUWAX (2000-10000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSTU" && tradeValue <= 10000\'
        expression: "30.0"

      - name: "Strukturierte Produkte EUWAX (10000-15000)"
