        expression: "55.0"

      - name: "Strukturierte Produkte EUWAX (ab 15000)"
        condition: \'instrument == "ISSUER_RISK_PRODUCT" && mic == "XSTU"\'
        expression: "80.0"

      # ── AKTIEN – SIX / BX Swiss (CHF) ──────────────────────────────────
      - name: "SIX / BX Swiss (0-500)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && tradeValue <= 500\'
        expression: "3.0"

      - name: "SIX / BX Swiss (500-2000)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && tradeValue <= 2000\'
        expression: "20.0"

