        condition: \'(mic == "XSWX" || mic == "XBRN") && tradeValue <= 50000\'
        expression: "135.0"

      - name: "SIX / BX Swiss (ab 50000)"
        condition: \'mic == "XSWX" || mic == "XBRN"\'
        expression: "190.0"

      # ── AKTIEN – Xetra (EUR) ───────────────────────────────────────────
      - name: "Xetra (0-1000)"
        condition: \'mic == "XETR" && tradeValue <= 1000\'
        expression: "5.0"

