      - name: "US-Börsen (15000-25000)"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE") && tradeValue <= 25000\'
        expression: "80.0"

      - name: "US-Börsen (25000-50000)"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE") && tradeValue <= 50000\'
        expression: "135.0"

      - name: "US-Börsen (ab 50000)"
        condition: \'mic == "XNYS" || mic == "XNAS" || mic == "XASE"\'
        expression: "190.0"

      # ── AKTIEN – Toronto TSX, TSX Venture (CAD) ────────────────────────
      - name: "Kanada (0-2000)"
        condition: \'(mic == "XTSE" || mic == "XTSX") && tradeValue <= 2000\'
        expression: "25.0"

      - name: "Kanada (2000-10000)"
        condition: \'(mic == "XTSE" || mic == "XTSX") && tradeValue <= 10000\'
        expression: "30.0"

      - name: "Kanada (10000-15000)"
        condition: \'(mic == "XTSE" || mic == "XTSX") && tradeValue <= 15000\'
        expression: "55.0"

      - name: "Kanada (15000-25000)"
        condition: \'(mic == "XTSE" || mic == "XTSX") && tradeValue <= 25000\'
        expression: "80.0"

      - name: "Kanada (25000-50000)"
        condition: \'(mic == "XTSE" || mic == "XTSX") && tradeValue <= 50000\'
        expression: "135.0"

      - name: "Kanada (ab 50000)"
        condition: \'mic == "XTSE" || mic == "XTSX"\'
        expression: "190.0"

      # ── AUFFANGREGEL ───────────────────────────────────────────────────
      - name: "Standard (unbekannter Börsenplatz)"
        condition: "true"
        expression: >-
          IF(tradeValue <= 2000, 25.0,
          IF(tradeValue <= 10000, 30.0,
          IF(tradeValue <= 15000, 55.0,
          IF(tradeValue <= 25000, 80.0,
          IF(tradeValue <= 50000, 135.0,
          190.0)))))

  # ==========================================================================
  # PERIODE 2: ab 2024 (leicht angepasste SIX-Börsengebühren)
  # ==========================================================================
  - validFrom: "2024-01-01"
    rules:

      # ── ETF LEADERS (SIX) – Courtage + SIX-Börsengebühren (angepasst) ──
      - name: "ETF Leaders SIX (0-500)"
        condition: \'instrument == "ETF" && mic == "XSWX" && tradeValue <= 500\'
        expression: "3.0 + MAX(2.0, tradeValue * 0.00025)"

      - name: "ETF Leaders SIX (500-1000)"
        condition: \'instrument == "ETF" && mic == "XSWX" && tradeValue <= 1000\'
        expression: "5.0 + MAX(2.2, tradeValue * 0.00020)"

      - name: "ETF Leaders SIX (ab 1000)"
        condition: \'instrument == "ETF" && mic == "XSWX"\'
        expression: "9.0 + MAX(2.2, 1.3 + tradeValue * 0.00016)"

      # ── SWISS DOTS – Flat Fee CHF 9 ─────────────────────────────────────
      - name: "Swiss DOTS Flat Fee"
        condition: \'mic == "SDOT"\'
        expression: "9.0"

      # ── FONDS ───────────────────────────────────────────────────────────
      - name: "Fonds (Tier 0 – Swissquote Depotbank)"
        condition: \'instrument == "MUTUAL_FUND" && mic == "SQT0"\'
        expression: "0.0"

      - name: "Fonds (Tier A+ – Prime Partner, Flat 9)"
        condition: \'instrument == "MUTUAL_FUND" && mic == "SQAP"\'
        expression: "9.0"

      - name: "Fonds (Standard – 0.5%, min 9, max 250)"
        condition: \'instrument == "MUTUAL_FUND"\'
        expression: "MAX(9.0, MIN(250.0, tradeValue * 0.005))"

      # ── OTC ─────────────────────────────────────────────────────────────
      - name: "OTC Orders"
        condition: \'mic == "OTCX"\'
        expression: "MAX(100.0, tradeValue * 0.005)"

      # ── OBLIGATIONEN – SIX ─────────────────────────────────────────────
      - name: "Obligationen CH (0-500)"
        condition: \'assetclass == "FIXED_INCOME" && mic == "XSWX" && tradeValue <= 500\'
        expression: "9.0"

      - name: "Obligationen CH (500-2000)"
