custody:
  periods:
    - validFrom: "1900-01-01"
      validTo: "2022-12-31"
      status: ASSUMED
      source: "https://finanzdepot.ch/swissquote-update-tarife-senkung-oder-erhoehung/"
      note: "Approximation: the tariff valid until December 2022 applied to the whole earlier history. 0.025 percent per quarter of the securities value at quarter end, cash excluded, at least CHF 15 and at most CHF 40 per quarter; plus VAT at today\'s rate."
      currency: CHF
      valuation: PERIOD_END
      billingMonths: 3
      collection: END
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      closingPolicy: PRORATED
      amount: \'assetValue * 0.001\'
      minimum: 15
      maximum: 40
      vatRate: 0.081
    - validFrom: "2023-01-01"
      status: ASSUMED
      source: "https://www.swissquote.com/de-ch/private/trade/pricing/account-fees"
      note: "Fixed quarterly tiers since January 2023 on the securities value at quarter end, cash excluded: CHF 20 up to 50,000, 25 up to 100,000, 37.50 up to 150,000, 50 above. The additional 0.0075 percent per quarter above CHF 1 million is applied to the whole value, which the tariff leaves open; plus VAT at today\'s rate."
      currency: CHF
      valuation: PERIOD_END
      billingMonths: 3
      collection: END
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      closingPolicy: PRORATED
      amount: \'4 * (IF(assetValue <= 50000, 20, IF(assetValue <= 100000, 25, IF(assetValue <= 150000, 37.5, 50))) + IF(assetValue > 1000000, assetValue * 0.000075, 0))\'
      vatRate: 0.081

fx:
  currencyClasses:
    MAJOR: [USD, EUR, JPY, GBP, CHF, AUD, CAD, NZD]
    MINOR: [NOK, SEK, DKK, SGD, HUF, PLN, CZK, CNH]
    EMERGING: [HKD, MXN, ZAR, TRY, THB, ILS]
    OTHER: [AED, SAR, KWD, QAR, OMR, BHD]
  periods:
    - validFrom: "1900-01-01"
      status: ASSUMED
      source: "https://www.swissquote.com/de-ch/private/trade/pricing/securities/currency-exchange"
      note: "Class matrix observed 2026-09 on the currency exchange page, applied to the whole history and to conversions inside trades, transfers and income. Degressive rates above CHF 50,000 have no published schedule and are not modelled."
      rules:
        - name: Major/Major
          condition: "payClass == \'MAJOR\' && receiveClass == \'MAJOR\'"
          expression: "0.95"
        - name: Major/Other, Other/Other
          condition: "(payClass == \'OTHER\' || receiveClass == \'OTHER\') && (payClass == \'MAJOR\' || receiveClass == \'MAJOR\' || payClass == receiveClass)"
          expression: "1.00"
        - name: Major/Minor
          condition: "(payClass == \'MAJOR\' && receiveClass == \'MINOR\') || (payClass == \'MINOR\' && receiveClass == \'MAJOR\')"
          expression: "1.25"
        - name: Major/Emerging, Minor/Minor, Minor/Other
          condition: "(payClass == \'MAJOR\' && receiveClass == \'EMERGING\') || (payClass == \'EMERGING\' && receiveClass == \'MAJOR\') || (payClass == \'MINOR\' && receiveClass == \'MINOR\') || (payClass == \'MINOR\' && receiveClass == \'OTHER\') || (payClass == \'OTHER\' && receiveClass == \'MINOR\')"
          expression: "1.50"
        - name: Minor/Emerging, Emerging/Other
          condition: "(payClass == \'MINOR\' && receiveClass == \'EMERGING\') || (payClass == \'EMERGING\' && receiveClass == \'MINOR\') || (payClass == \'EMERGING\' && receiveClass == \'OTHER\') || (payClass == \'OTHER\' && receiveClass == \'EMERGING\')"
          expression: "2.00"
        - name: Emerging/Emerging
          condition: "payClass == \'EMERGING\' && receiveClass == \'EMERGING\'"
          expression: "2.50"
', NULL);
# Cornèrtrader (Cornèr Bank AG) Gebührenmodell – Version 2
# Quelle: cornertrader.ch/de/preise/ (Stand 2026)
#         moneyland.ch (Mindestgebühren und Detaildaten)
#         Backtest gegen 369 reale Transaktionen (2009–2026)
# ============================================================================
# ÄNDERUNGEN gegenüber v1:
#   - NEU: periods-Format (alt vs. aktuell) statt flat rules
#   - NEU: FOREX-Regeln (vorher Fallback → 2\'000–5\'000% Fehler)
#   - NEU: CFD-Regeln (vorher Standard-Aktien-Tarif → 27–63% Fehler)
#   - FIX: Historische Mindestgebühren (SIX CHF 18, Xetra EUR 18, US USD 12)
#   - FIX: Madrid/IBEX eigener Tarif (0.20% statt 0.15%)
#
# HINWEIS fixedAssets:
#   Die Stufe (Consistency/Solidity/Opportunity/Energy) hängt vom
#   Gesamt-Depotwert ab. Wenn fixedAssets=0 oder nicht gesetzt ist,
#   wird immer Consistency (teuerster Tarif) angewendet.
#   Für korrekte Ergebnisse muss fixedAssets dem tatsächlichen
#   Depotwert entsprechen!
# ============================================================================

periods:

  # ========================================================================
  # PERIODE 1: Altes Preismodell (2009 – Ende 2023)
  # Höhere Mindestgebühren, nur Consistency-Stufe relevant
  # ========================================================================
  - validFrom: "2009-01-01"
    validTo: "2023-12-31"
    rules:

      # --- FOREX (OTC, kein MIC) -----------------------------------------
      # Forex-Gebühren sind sehr tief (~0.01% in der alten Periode)
      # 2022-06-30 EUR/CHF: 12.70 / 100\'000 = 0.0127%
      - name: "Forex (alt)"
        condition: \'instrument == "FOREX"\'
        expression: "MAX(10.0, tradeValue * 0.00013)"

      # --- CFD US-Börsen --------------------------------------------------
      # Flat Fee USD 20 für US-CFDs (Pfizer, Alphabet, Oracle)
      # Ausnahme: Peloton hatte USD 40 – möglicherweise Sonderfall
      - name: "CFD US (alt)"
        condition: \'instrument == "CFD" && (mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX")\'
        expression: "20.0"

      # --- SIX SWISS EXCHANGE / BX SWISS (altes Minimum CHF 18) ----------
      - name: "Aktien/ETF SIX – Energy (alt, Depot ab 500k)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && fixedAssets >= 500000\'
        expression: "MAX(10.0, tradeValue * 0.0007)"

      - name: "Aktien/ETF SIX – Opportunity (alt, Depot ab 250k)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && fixedAssets >= 250000\'
        expression: "MAX(14.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF SIX – Solidity (alt, Depot ab 100k)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && fixedAssets >= 100000\'
        expression: "MAX(18.0, tradeValue * 0.001)"

      - name: "Aktien/ETF SIX – Consistency (alt)"
        condition: \'mic == "XSWX" || mic == "XBRN"\'
        expression: "MAX(18.0, tradeValue * 0.0012)"

      # --- SIX STRUCTURED PRODUCTS (altes Minimum CHF 18) ----------------
      - name: "Strukturierte Produkte SIX – Consistency (alt)"
        condition: \'mic == "XSTX"\'
        expression: "MAX(18.0, tradeValue * 0.0012)"

      # --- XETRA / FRANKFURT (altes Minimum EUR 18) ----------------------
      - name: "Aktien/ETF Xetra – Energy (alt)"
        condition: \'(mic == "XETR" || mic == "XETF" || mic == "XFRA") && fixedAssets >= 500000\'
        expression: "MAX(12.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF Xetra – Opportunity (alt)"
        condition: \'(mic == "XETR" || mic == "XETF" || mic == "XFRA") && fixedAssets >= 250000\'
        expression: "MAX(12.0, tradeValue * 0.001)"

      - name: "Aktien/ETF Xetra – Solidity (alt)"
        condition: \'(mic == "XETR" || mic == "XETF" || mic == "XFRA") && fixedAssets >= 100000\'
        expression: "MAX(18.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF Xetra – Consistency (alt)"
        condition: \'mic == "XETR" || mic == "XETF" || mic == "XFRA"\'
        expression: "MAX(18.0, tradeValue * 0.0015)"

      # --- US-BÖRSEN (altes Minimum USD 12) -------------------------------
      - name: "Aktien/ETF US – Energy (alt)"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX") && fixedAssets >= 500000\'
        expression: "MAX(10.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF US – Opportunity (alt)"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX") && fixedAssets >= 250000\'
        expression: "MAX(10.0, tradeValue * 0.001)"

      - name: "Aktien/ETF US – Solidity (alt)"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX") && fixedAssets >= 100000\'
        expression: "MAX(12.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF US – Consistency (alt)"
        condition: \'mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX"\'
        expression: "MAX(12.0, tradeValue * 0.0015)"

      # --- LONDON STOCK EXCHANGE (altes Minimum GBP 15) ------------------
      - name: "Aktien/ETF London – Consistency (alt)"
        condition: \'mic == "XLON"\'
        expression: "MAX(15.0, tradeValue * 0.0015)"

      # --- EURONEXT (altes Minimum EUR 18) --------------------------------
      - name: "Aktien/ETF Euronext – Consistency (alt)"
        condition: \'mic == "XPAR" || mic == "XAMS" || mic == "XBRU" || mic == "XLIS" || mic == "XDUB"\'
        expression: "MAX(18.0, tradeValue * 0.0015)"

      # --- MADRID / IBEX (0.20% basierend auf Backtest-Daten) -------------
      # 2022-06-30: TV=20080, actual=40.16 → 0.20%
      # 2023-01-18: TV=22370, actual=44.74 → 0.20%
      - name: "Aktien/ETF Madrid – Consistency (alt)"
        condition: \'mic == "XMAD"\'
        expression: "MAX(18.0, tradeValue * 0.002)"

      # --- ÜBRIGE EUROPÄISCHE BÖRSEN (altes Minimum EUR 18) ---------------
      - name: "Aktien/ETF übrige EU – Consistency (alt)"
        condition: \'mic == "XMIL" || mic == "XWBO" || mic == "XOSL" || mic == "XSTO" || mic == "XCSE" || mic == "XHEL"\'
        expression: "MAX(18.0, tradeValue * 0.0015)"

      # --- KANADISCHE BÖRSEN (altes Minimum CAD 18) -----------------------
      - name: "Aktien/ETF Kanada – Consistency (alt)"
        condition: \'mic == "XTSE" || mic == "XTSX"\'
        expression: "MAX(18.0, tradeValue * 0.002)"

      # --- FALLBACK -------------------------------------------------------
      - name: "Fallback (alt)"
        condition: "true"
        expression: "MAX(18.0, tradeValue * 0.0015)"

  # ========================================================================
  # PERIODE 2: Aktuelles Preismodell (ab 2024)
  # Tiefere Mindestgebühren, alle 4 Stufen
  # Quelle: cornertrader.ch/de/preise/ (Stand 2026)
  # ========================================================================
  - validFrom: "2024-01-01"
    rules:

      # --- FOREX (OTC, kein MIC) -----------------------------------------
      # Forex-Gebühren bei Cornèrtrader sind sehr tief.
      # Analyse der Backtest-Daten:
      #   2024-12:  ~0.003% (2.64 CHF / 87k)
      #   2025 Q1:  ~0.003–0.005%
      #   2025 Q3+: ~0.003% (2.40 CHF / 80k)
      # Modellierung: ~0.005% mit Minimum CHF 2
      # Hinweis: Die tatsächlichen Kosten könnten Spread-basiert sein
      # und sind daher schwer exakt zu modellieren.
      - name: "Forex – Energy (Depot ab 500k)"
        condition: \'instrument == "FOREX" && fixedAssets >= 500000\'
        expression: "MAX(2.0, tradeValue * 0.00003)"

      - name: "Forex – Opportunity (Depot ab 250k)"
        condition: \'instrument == "FOREX" && fixedAssets >= 250000\'
        expression: "MAX(2.0, tradeValue * 0.00005)"

      - name: "Forex – Consistency"
        condition: \'instrument == "FOREX"\'
        expression: "MAX(5.0, tradeValue * 0.0001)"

      # --- CFD US-BÖRSEN --------------------------------------------------
      # Backtest zeigt: Flat Fee USD 20 für US-CFDs
      # (Pfizer, Alphabet, Oracle alle bei exakt 20.00)
      - name: "CFD US"
        condition: \'instrument == "CFD" && (mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX")\'
        expression: "20.0"

      # --- CFD Übrige (Fallback für nicht-US CFDs) ------------------------
      - name: "CFD übrige"
        condition: \'instrument == "CFD"\'
        expression: "20.0"

      # --- SIX SWISS EXCHANGE / BX SWISS ----------------------------------
      # ENERGY:      0.07%, min CHF 5
      # OPPORTUNITY: 0.08%, min CHF 7
      # SOLIDITY:    0.10%, min CHF 9
      # CONSISTENCY: 0.12%, min CHF 9
      - name: "Aktien/ETF SIX – Energy (Depot ab 500k)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && fixedAssets >= 500000\'
        expression: "MAX(5.0, tradeValue * 0.0007)"

      - name: "Aktien/ETF SIX – Opportunity (Depot ab 250k)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && fixedAssets >= 250000\'
        expression: "MAX(7.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF SIX – Solidity (Depot ab 100k)"
        condition: \'(mic == "XSWX" || mic == "XBRN") && fixedAssets >= 100000\'
        expression: "MAX(9.0, tradeValue * 0.001)"

      - name: "Aktien/ETF SIX – Consistency"
        condition: \'mic == "XSWX" || mic == "XBRN"\'
        expression: "MAX(9.0, tradeValue * 0.0012)"

      # --- SIX STRUCTURED PRODUCTS ----------------------------------------
      - name: "Strukturierte Produkte SIX – Energy"
        condition: \'mic == "XSTX" && fixedAssets >= 500000\'
        expression: "MAX(5.0, tradeValue * 0.0007)"

      - name: "Strukturierte Produkte SIX – Opportunity"
        condition: \'mic == "XSTX" && fixedAssets >= 250000\'
        expression: "MAX(7.0, tradeValue * 0.0008)"

      - name: "Strukturierte Produkte SIX – Solidity"
        condition: \'mic == "XSTX" && fixedAssets >= 100000\'
        expression: "MAX(9.0, tradeValue * 0.001)"

      - name: "Strukturierte Produkte SIX – Consistency"
        condition: \'mic == "XSTX"\'
        expression: "MAX(9.0, tradeValue * 0.0012)"

      # --- XETRA / FRANKFURT ----------------------------------------------
      # ENERGY:      0.08%, min EUR 8
      # OPPORTUNITY: 0.10%, min EUR 8
      # SOLIDITY:    0.12%, min EUR 12
      # CONSISTENCY: 0.15%, min EUR 12
      - name: "Aktien/ETF Xetra – Energy"
        condition: \'(mic == "XETR" || mic == "XETF" || mic == "XFRA") && fixedAssets >= 500000\'
        expression: "MAX(8.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF Xetra – Opportunity"
        condition: \'(mic == "XETR" || mic == "XETF" || mic == "XFRA") && fixedAssets >= 250000\'
        expression: "MAX(8.0, tradeValue * 0.001)"

      - name: "Aktien/ETF Xetra – Solidity"
        condition: \'(mic == "XETR" || mic == "XETF" || mic == "XFRA") && fixedAssets >= 100000\'
        expression: "MAX(12.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF Xetra – Consistency"
        condition: \'mic == "XETR" || mic == "XETF" || mic == "XFRA"\'
        expression: "MAX(12.0, tradeValue * 0.0015)"

      # --- US-BÖRSEN ------------------------------------------------------
      # ENERGY:      0.08%, min USD 10
      # OPPORTUNITY: 0.10%, min USD 10
      # SOLIDITY:    0.12%, min USD 15
      # CONSISTENCY: 0.15%, min USD 15
      - name: "Aktien/ETF US – Energy"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX") && fixedAssets >= 500000\'
        expression: "MAX(10.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF US – Opportunity"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX") && fixedAssets >= 250000\'
        expression: "MAX(10.0, tradeValue * 0.001)"

      - name: "Aktien/ETF US – Solidity"
        condition: \'(mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX") && fixedAssets >= 100000\'
        expression: "MAX(15.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF US – Consistency"
        condition: \'mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX"\'
        expression: "MAX(15.0, tradeValue * 0.0015)"

      # --- LONDON STOCK EXCHANGE ------------------------------------------
      - name: "Aktien/ETF London – Energy"
        condition: \'mic == "XLON" && fixedAssets >= 500000\'
        expression: "MAX(8.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF London – Opportunity"
        condition: \'mic == "XLON" && fixedAssets >= 250000\'
        expression: "MAX(8.0, tradeValue * 0.001)"

      - name: "Aktien/ETF London – Solidity"
        condition: \'mic == "XLON" && fixedAssets >= 100000\'
        expression: "MAX(12.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF London – Consistency"
        condition: \'mic == "XLON"\'
        expression: "MAX(12.0, tradeValue * 0.0015)"

      # --- EURONEXT -------------------------------------------------------
      - name: "Aktien/ETF Euronext – Energy"
        condition: \'(mic == "XPAR" || mic == "XAMS" || mic == "XBRU" || mic == "XLIS" || mic == "XDUB") && fixedAssets >= 500000\'
        expression: "MAX(8.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF Euronext – Opportunity"
        condition: \'(mic == "XPAR" || mic == "XAMS" || mic == "XBRU" || mic == "XLIS" || mic == "XDUB") && fixedAssets >= 250000\'
        expression: "MAX(8.0, tradeValue * 0.001)"

      - name: "Aktien/ETF Euronext – Solidity"
        condition: \'(mic == "XPAR" || mic == "XAMS" || mic == "XBRU" || mic == "XLIS" || mic == "XDUB") && fixedAssets >= 100000\'
        expression: "MAX(12.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF Euronext – Consistency"
        condition: \'mic == "XPAR" || mic == "XAMS" || mic == "XBRU" || mic == "XLIS" || mic == "XDUB"\'
        expression: "MAX(12.0, tradeValue * 0.0015)"

      # --- MADRID (höherer Satz basierend auf Backtest) -------------------
      - name: "Aktien/ETF Madrid – Energy"
        condition: \'mic == "XMAD" && fixedAssets >= 500000\'
        expression: "MAX(8.0, tradeValue * 0.001)"

      - name: "Aktien/ETF Madrid – Opportunity"
        condition: \'mic == "XMAD" && fixedAssets >= 250000\'
        expression: "MAX(8.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF Madrid – Solidity"
        condition: \'mic == "XMAD" && fixedAssets >= 100000\'
        expression: "MAX(12.0, tradeValue * 0.0015)"

      - name: "Aktien/ETF Madrid – Consistency"
        condition: \'mic == "XMAD"\'
        expression: "MAX(12.0, tradeValue * 0.002)"

      # --- ÜBRIGE EUROPÄISCHE BÖRSEN --------------------------------------
      - name: "Aktien/ETF übrige EU – Energy"
        condition: \'(mic == "XMIL" || mic == "XWBO" || mic == "XOSL" || mic == "XSTO" || mic == "XCSE" || mic == "XHEL") && fixedAssets >= 500000\'
        expression: "MAX(8.0, tradeValue * 0.0008)"

      - name: "Aktien/ETF übrige EU – Opportunity"
        condition: \'(mic == "XMIL" || mic == "XWBO" || mic == "XOSL" || mic == "XSTO" || mic == "XCSE" || mic == "XHEL") && fixedAssets >= 250000\'
        expression: "MAX(8.0, tradeValue * 0.001)"

      - name: "Aktien/ETF übrige EU – Solidity"
        condition: \'(mic == "XMIL" || mic == "XWBO" || mic == "XOSL" || mic == "XSTO" || mic == "XCSE" || mic == "XHEL") && fixedAssets >= 100000\'
        expression: "MAX(12.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF übrige EU – Consistency"
        condition: \'mic == "XMIL" || mic == "XWBO" || mic == "XOSL" || mic == "XSTO" || mic == "XCSE" || mic == "XHEL"\'
        expression: "MAX(12.0, tradeValue * 0.0015)"

      # --- KANADISCHE BÖRSEN ----------------------------------------------
      - name: "Aktien/ETF Kanada – Energy"
        condition: \'(mic == "XTSE" || mic == "XTSX") && fixedAssets >= 500000\'
        expression: "MAX(10.0, tradeValue * 0.001)"

      - name: "Aktien/ETF Kanada – Opportunity"
        condition: \'(mic == "XTSE" || mic == "XTSX") && fixedAssets >= 250000\'
        expression: "MAX(10.0, tradeValue * 0.0012)"

      - name: "Aktien/ETF Kanada – Solidity"
        condition: \'(mic == "XTSE" || mic == "XTSX") && fixedAssets >= 100000\'
        expression: "MAX(15.0, tradeValue * 0.0015)"

      - name: "Aktien/ETF Kanada – Consistency"
        condition: \'mic == "XTSE" || mic == "XTSX"\'
        expression: "MAX(15.0, tradeValue * 0.002)"

      # --- FALLBACK -------------------------------------------------------
      - name: "Fallback – Energy"
        condition: "fixedAssets >= 500000"
        expression: "MAX(8.0, tradeValue * 0.0008)"

      - name: "Fallback – Opportunity"
        condition: "fixedAssets >= 250000"
        expression: "MAX(8.0, tradeValue * 0.001)"

      - name: "Fallback – Solidity"
        condition: "fixedAssets >= 100000"
        expression: "MAX(12.0, tradeValue * 0.0012)"

      - name: "Fallback – Consistency"
        condition: "true"
        expression: "MAX(12.0, tradeValue * 0.0015)"
custody:
  periods:
    - validFrom: "1900-01-01"
      validTo: "2025-12-31"
      status: VERIFIED
      source: "https://thepoorswiss.com/cornertrader-review/"
      note: "No custody fee until the end of 2025. The inactivity fee charged between 2019 and 2024 was no custody fee and is not modelled."
      currency: CHF
      valuation: NONE
      billingMonths: 3
      collection: START
      billingDay: 0
      dayCount: ACTUAL_ACTUAL
      amount: \'0\'
    - validFrom: "2026-01-01"
      status: VERIFIED
      source: "https://www.cornertrader.ch/en/pricing/"
      note: "Introduced 1 January 2026 for equities and ETFs only, billed quarterly. The tier of each day\'s value accrues its annual amount over 360 days: free up to CHF 10,000, then CHF 80, 100, 200, 240, 280 a year, above CHF 1 million 0.05 percent, at most CHF 5,000 a year; plus VAT."
      currency: CHF
      valuation: DAILY
      billingMonths: 3
      collection: END
      billingDay: 0
      dayCount: ACTUAL_360
      closingPolicy: ACCRUED
      amount: \'IF(assetValue <= 10000, 0, IF(assetValue <= 50000, 80, IF(assetValue <= 100000, 100, IF(assetValue <= 250000, 200, IF(assetValue <= 500000, 240, IF(assetValue <= 1000000, 280, assetValue * 0.0005))))))\'
      annualCap: 5000
      vatRate: 0.081
      valueRules:
        - name: \'Equities and ETFs\'
          condition: \'instrument == "ETF" || (instrument == "DIRECT_INVESTMENT" && assetclass == "EQUITIES")\'
          expression: \'positionValue\'
        - name: \'Other instruments\'
          condition: \'true\'
          expression: \'0\'
', NULL);
# Raiffeisen Schweiz E-Banking Gebührenmodell
# Quelle: Dienstleistungspreise Anlegen, gültig ab 1. Januar 2026
#         (Raiffeisenbank Regio Frick-Mettauertal als Referenz)
# ============================================================================
# WICHTIG:
#   - Raiffeisen ist ein Genossenschaftsverbund – die Tarife können je
#     nach lokaler Raiffeisenbank leicht abweichen!
#   - Raiffeisen verwendet einen STAFFELTARIF:
#       Für die ersten CHF 100\'000: Satz A
#       Für Beträge über CHF 100\'000: Satz B (nur auf den Mehrbetrag)
#       Die Teilbeträge werden addiert.
#   - E-Banking-Tarif = 50% des Standard-Tarifs
#   - Alle Regeln hier bilden den E-BANKING-Tarif ab.
#   - Fonds-Rücknahmen sind generell kostenlos.
#   - Courtagen sind MwSt-frei. Steuern/Börsengebühren separat.
# ============================================================================

rules:

  # ==========================================================================
  # FONDS – RÜCKNAHME (alle Fonds: Raiffeisen + Drittanbieter)
  # Kostenlos gemäss Webseite
  # ==========================================================================
  - name: "Fonds Rücknahme (kostenlos)"
    condition: \'instrument == "MUTUAL_FUND" && tradeDirection == 1\'
    expression: "0.0"

  # ==========================================================================
  # FONDS – Geldmarkt- & Obligationenfonds (Zeichnung/Kauf)
  # E-Banking: 0.40% erste 100k, 0.075% darüber, min CHF 5
  # (Standard: 0.80% / 0.15% / min CHF 10)
  # Steuerung über assetclass: MONEY_MARKET oder FIXED_INCOME + MUTUAL_FUND
  # ==========================================================================
  - name: "Geldmarkt-/Obligationenfonds E-Banking (bis 100k)"
    condition: \'instrument == "MUTUAL_FUND" && (assetclass == "MONEY_MARKET" || assetclass == "FIXED_INCOME") && tradeValue <= 100000\'
    expression: "MAX(5.0, tradeValue * 0.004)"

  - name: "Geldmarkt-/Obligationenfonds E-Banking (ab 100k)"
    condition: \'instrument == "MUTUAL_FUND" && (assetclass == "MONEY_MARKET" || assetclass == "FIXED_INCOME")\'
    expression: "MAX(5.0, 100000 * 0.004 + (tradeValue - 100000) * 0.00075)"

  # ==========================================================================
  # FONDS – Aktien-, Anlageziel- & übrige Fonds (Zeichnung/Kauf)
  # E-Banking: 0.75% erste 100k, 0.15% darüber, min CHF 5
  # (Standard: 1.50% / 0.30% / min CHF 10)
  # ==========================================================================
  - name: "Aktienfonds / übrige Fonds E-Banking (bis 100k)"
    condition: \'instrument == "MUTUAL_FUND" && tradeValue <= 100000\'
    expression: "MAX(5.0, tradeValue * 0.0075)"

  - name: "Aktienfonds / übrige Fonds E-Banking (ab 100k)"
    condition: \'instrument == "MUTUAL_FUND"\'
    expression: "MAX(5.0, 100000 * 0.0075 + (tradeValue - 100000) * 0.0015)"

  # ==========================================================================
  # OBLIGATIONEN – Börsenplatz Schweiz
  # E-Banking: 0.35% erste 100k, 0.075% darüber, min CHF 5
  # (Standard: 0.70% / 0.15% / min CHF 10)
  # MICs: XSWX, XBRN, XSTX
  # ==========================================================================
  - name: "Obligationen CH E-Banking (bis 100k)"
    condition: \'assetclass == "FIXED_INCOME" && (mic == "XSWX" || mic == "XBRN" || mic == "XSTX") && tradeValue <= 100000\'
    expression: "MAX(5.0, tradeValue * 0.0035)"

  - name: "Obligationen CH E-Banking (ab 100k)"
    condition: \'assetclass == "FIXED_INCOME" && (mic == "XSWX" || mic == "XBRN" || mic == "XSTX")\'
    expression: "MAX(5.0, 100000 * 0.0035 + (tradeValue - 100000) * 0.00075)"

  # ==========================================================================
  # OBLIGATIONEN – Börsenplatz Ausland / OTC
  # Gleicher Tarif wie Aktien Ausland:
  # E-Banking: 0.75% erste 100k, 0.15% darüber, min CHF 10
  # ==========================================================================
  - name: "Obligationen Ausland/OTC E-Banking (bis 100k)"
    condition: \'assetclass == "FIXED_INCOME" && tradeValue <= 100000\'
    expression: "MAX(10.0, tradeValue * 0.0075)"

  - name: "Obligationen Ausland/OTC E-Banking (ab 100k)"
    condition: \'assetclass == "FIXED_INCOME"\'
    expression: "MAX(10.0, 100000 * 0.0075 + (tradeValue - 100000) * 0.0015)"

  # ==========================================================================
  # AKTIEN / ETF / STRUKTURIERTE PRODUKTE – Börsenplatz Schweiz
  # E-Banking: 0.50% erste 100k, 0.10% darüber, min CHF 5
  # (Standard: 1.00% / 0.20% / min CHF 10)
  # Schweiz = SIX Swiss Exchange, BX Swiss, SIX Structured Products
  # MICs: XSWX, XBRN, XSTX
  # ==========================================================================
  - name: "Aktien/ETF/Struki Schweiz E-Banking (bis 100k)"
    condition: \'(mic == "XSWX" || mic == "XBRN" || mic == "XSTX") && tradeValue <= 100000\'
    expression: "MAX(5.0, tradeValue * 0.005)"

  - name: "Aktien/ETF/Struki Schweiz E-Banking (ab 100k)"
    condition: \'mic == "XSWX" || mic == "XBRN" || mic == "XSTX"\'
    expression: "MAX(5.0, 100000 * 0.005 + (tradeValue - 100000) * 0.001)"

  # ==========================================================================
  # AKTIEN / ETF / STRUKTURIERTE PRODUKTE – Börsenplatz Ausland & OTC
  # E-Banking: 0.75% erste 100k, 0.15% darüber, min CHF 10
  # (Standard: 1.50% / 0.30% / min CHF 20)
  # Alle anderen MICs (inkl. XETR, XFRA, XPAR, XLON, XNYS, XNAS etc.)
  # ==========================================================================
  - name: "Aktien/ETF/Struki Ausland E-Banking (bis 100k)"
    condition: "tradeValue <= 100000"
    expression: "MAX(10.0, tradeValue * 0.0075)"

  - name: "Aktien/ETF/Struki Ausland E-Banking (ab 100k)"
    condition: "true"
    expression: "MAX(10.0, 100000 * 0.0075 + (tradeValue - 100000) * 0.0015)"', NULL);
# TradeDirect (Banque Cantonale Vaudoise BCV) Gebührenmodell
# Quelle: tradedirect.ch/de/home/vorteile-und-tarife.html
#         Tarife und Bedingungen PDF (42-102a/25.02)
#         moneyland.ch (ergänzende Staffeln ab CHF 25\'000)
# ============================================================================
# Hinweise:
#   - TradeDirect arbeitet mit Flat-Fee-Staffeln pro Auftrag.
#   - 4 Börsengruppen mit unterschiedlichen Tarifen und Währungen.
#   - SIX Structured Products: gedeckelt auf CHF 69.90 ab CHF 15\'000.
#   - Nicht kotierte Fonds: Kauf = Courtage, Verkauf = kostenlos.
#   - BCV-Emissionen (Struki, Kassenobligationen): Zeichnung kostenlos.
#   - Stempel-, Börsen- und gesetzliche Abgaben NICHT inbegriffen.
#   - Regeln werden von oben nach unten ausgewertet (first match wins).
# ============================================================================

rules:

  # ==========================================================================
  # FONDS – VERKAUF / RÜCKNAHME (nicht kotierte Fonds)
  # Verkauf kostenlos
  # ==========================================================================
  - name: "Fonds Verkauf/Rücknahme (kostenlos)"
    condition: \'instrument == "MUTUAL_FUND" && tradeDirection == 1\'
    expression: "0.0"

  # ==========================================================================
  # BCV-EMISSIONEN – Zeichnung kostenlos
  # Strukturierte Produkte der BCV, BCV-Kassenobligationen
  # Platzhalter-MIC: BCVE (BCV Emission)
  # ==========================================================================
  - name: "BCV Emissionen – Zeichnung (kostenlos)"
    condition: \'mic == "BCVE" && tradeDirection == 0\'
    expression: "0.0"

  # ==========================================================================
  # SIX STRUCTURED PRODUCTS EXCHANGE
  # Selber Tarif wie SIX Swiss Exchange, aber GEDECKELT auf CHF 69.90
  # für Aufträge über CHF 15\'000.
  # MIC: XSTX
  # ==========================================================================
  - name: "SIX Structured Products (gedeckelt ab 15k)"
    condition: \'mic == "XSTX"\'
    expression: >-
      IF(tradeValue <= 500, 3.90,
      IF(tradeValue <= 750, 5.90,
      IF(tradeValue <= 1000, 5.90,
      IF(tradeValue <= 2000, 10.90,
      IF(tradeValue <= 10000, 29.90,
      IF(tradeValue <= 15000, 44.90,
      69.90))))))

  # ==========================================================================
  # GRUPPE 1: Schweizer Börsen, London SETS, Xetra
  # Währung: CHF (SIX), GBP (London), EUR (Xetra)
  # MICs: XSWX, XBRN (SIX, BX Swiss)
  #        XLON (London SETS)
  #        XETR, XETF (Xetra, Xetra ETF)
  # Staffeln: 3.90 → 5.90 → 5.90 → 10.90 → 29.90 → 44.90 → 69.90
  #           → 114.90 → 164.90 → 199.90
  # ==========================================================================
  - name: "Aktien/ETF CH + London + Xetra"
    condition: \'mic == "XSWX" || mic == "XBRN" || mic == "XLON" || mic == "XETR" || mic == "XETF"\'
    expression: >-
      IF(tradeValue <= 500, 3.90,
      IF(tradeValue <= 1000, 5.90,
      IF(tradeValue <= 2000, 10.90,
      IF(tradeValue <= 10000, 29.90,
      IF(tradeValue <= 15000, 44.90,
      IF(tradeValue <= 25000, 69.90,
      IF(tradeValue <= 50000, 114.90,
      IF(tradeValue <= 75000, 164.90,
      199.90))))))))

  # ==========================================================================
  # GRUPPE 2: US-Börsen (NYSE, NASDAQ, NYSE American)
  # Währung: USD
  # MICs: XNYS, XNAS, XASE, ARCX (NYSE Arca)
  # Identische Staffeln wie Gruppe 1
  # ==========================================================================
  - name: "Aktien/ETF US-Börsen"
    condition: \'mic == "XNYS" || mic == "XNAS" || mic == "XASE" || mic == "ARCX"\'
    expression: >-
      IF(tradeValue <= 500, 3.90,
      IF(tradeValue <= 1000, 5.90,
      IF(tradeValue <= 2000, 10.90,
      IF(tradeValue <= 10000, 29.90,
      IF(tradeValue <= 15000, 44.90,
      IF(tradeValue <= 25000, 69.90,
      IF(tradeValue <= 50000, 114.90,
      IF(tradeValue <= 75000, 164.90,
      199.90))))))))

  # ==========================================================================
  # FRANKFURT PARKETT (Deutsche Börse AG)
  # Sondertarif: 0–15\'000 = pauschal EUR 44.90
  # Ab 15\'000: gleicher Tarif wie europäische Börsen
  # MIC: XFRA
  # ==========================================================================
  - name: "Frankfurt Parkett"
    condition: \'mic == "XFRA"\'
    expression: >-
      IF(tradeValue <= 15000, 44.90,
      IF(tradeValue <= 25000, 69.90,
      IF(tradeValue <= 50000, 114.90,
      IF(tradeValue <= 75000, 164.90,
      199.90))))

  # ==========================================================================
  # GRUPPE 3: Europäische Börsen (ohne Xetra/Frankfurt)
  # Euronext Paris, Amsterdam, Brüssel, Lissabon, Madrid,
  # Borsa Italiana, Helsinki, Nasdaq Stockholm, Oslo,
  # Nasdaq Copenhagen, Wiener Börse
  # Währung: EUR
  # Staffeln: 10.90 → 10.90 → 10.90 → 29.90 → 44.90 → 69.90
  #           → 114.90 → 164.90 → 199.90
  # ==========================================================================
  - name: "Aktien/ETF Europäische Börsen"
    condition: >-
      mic == "XPAR" || mic == "XAMS" || mic == "XBRU" || mic == "XLIS"
      || mic == "XMAD" || mic == "XMIL" || mic == "XHEL" || mic == "XSTO"
      || mic == "XOSL" || mic == "XCSE" || mic == "XWBO"
      || mic == "FNSE" || mic == "FNDK" || mic == "FNFI"
    expression: >-
      IF(tradeValue <= 2000, 10.90,
      IF(tradeValue <= 10000, 29.90,
      IF(tradeValue <= 15000, 44.90,
      IF(tradeValue <= 25000, 69.90,
      IF(tradeValue <= 50000, 114.90,
      IF(tradeValue <= 75000, 164.90,
      199.90))))))

  # ==========================================================================
  # GRUPPE 4: Kanadische Börsen (TSX, TSX Venture, CNSX)
  # Währung: CAD
  # Staffeln: 9.90 → 9.90 → 21.90 → 21.90 → 32.90 → 44.90 → 69.90
  #           → 114.90 → 164.90 → 199.90
  # MICs: XTSE, XTSX, XCNQ
  # ==========================================================================
  - name: "Aktien/ETF Kanada"
    condition: \'mic == "XTSE" || mic == "XTSX" || mic == "XCNQ"\'
    expression: >-
      IF(tradeValue <= 750, 9.90,
      IF(tradeValue <= 2000, 21.90,
      IF(tradeValue <= 10000, 32.90,
      IF(tradeValue <= 15000, 44.90,
      IF(tradeValue <= 25000, 69.90,
      IF(tradeValue <= 50000, 114.90,
      IF(tradeValue <= 75000, 164.90,
      199.90)))))))

  # ==========================================================================
  # FALLBACK – Unbekannte Börsenplätze
  # Europäischer Tarif als konservative Annahme
  # ==========================================================================
  - name: "Fallback (unbekannter Börsenplatz)"
    condition: "true"
    expression: >-
      IF(tradeValue <= 2000, 10.90,
      IF(tradeValue <= 10000, 29.90,
      IF(tradeValue <= 15000, 44.90,
      IF(tradeValue <= 25000, 69.90,
      IF(tradeValue <= 50000, 114.90,
      IF(tradeValue <= 75000, 164.90,
      199.90))))))', NULL);

-- udf_metadata: 5 row(s)

