-- user: 1 row(s)

-- CREATE_STOCK_EXCHANGE_CALENDAR_BY_RULE_SET for every rule based exchange
  VALUES (53, 20, NULL, NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0);
-- LOAD_ECB_CURRENCY_EXCHANGE_RATES, otherwise only at the next scheduled run
  VALUES (45, 20, NULL, NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0);

SET SQL_MODE = @OLD_SQL_MODE;
SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;
SET TIME_ZONE = @OLD_TIME_ZONE;
